<?php $imgs=glob(get_template_directory().'/assets/images/activity/*.{jpg,jpeg,png,JPG,JPEG,PNG}',GLOB_BRACE); if($imgs): ?><div class="activity-block"><div class="activity-title">Một số hình ảnh hoạt động</div><div class="activity-track"><?php foreach(array_slice($imgs,0,10) as $img): ?><img src="<?php echo esc_url(get_template_directory_uri().'/assets/images/activity/'.basename($img)); ?>" alt="Hình ảnh hoạt động DMC Miền Bắc"><?php endforeach; ?></div></div><?php endif; ?>
